/**
 * Bundled fixture database (public/fixtures.json), generated by scripts/ofl-import from the
 * Open Fixture Library. Array format, one fixture per line; channel names inline so that an OFL update
 * changes only the lines of the changed fixtures (gzip removes the repetition).
 */
export const FIXTURE_DB_FORMAT = 2;

export interface FixtureDbSource {
  readonly name: string;
  readonly url: string;
  readonly repository: string;
  /** git commit of the imported OFL version */
  readonly commit: string;
  /** commit date, YYYY-MM-DD */
  readonly date: string;
  readonly license: string;
}

/** [mode name, channel names in DMX order ('' = unused channel, OFL null channel)] */
export type DbMode = readonly [name: string, channels: readonly string[]];
/** [index into `manufacturers`, fixture key, fixture name, modes] */
export type DbFixture = readonly [manufacturer: number, key: string, name: string, modes: readonly DbMode[]];

export interface FixtureDatabase {
  readonly format: typeof FIXTURE_DB_FORMAT;
  readonly source: FixtureDbSource;
  /** [manufacturer key, display name] */
  readonly manufacturers: readonly (readonly [key: string, name: string])[];
  readonly fixtures: readonly DbFixture[];
}

export interface FixtureMode {
  readonly name: string;
  /** channel names in DMX order ('' = unused) */
  readonly channels: readonly string[];
}

export interface Fixture {
  /** stable id "manufacturerKey/fixtureKey" – used for favourites and saved patches */
  readonly id: string;
  readonly manufacturer: string;
  readonly name: string;
  readonly modes: readonly FixtureMode[];
}

const isString = (x: unknown): x is string => typeof x === 'string';
const isIndex = (x: unknown, length: number): x is number => Number.isInteger(x) && (x as number) >= 0 && (x as number) < length;

/** Structural check of the loaded JSON; returns undefined if it is not a valid database. */
export function parseFixtureDatabase(json: unknown): FixtureDatabase | undefined {
  if (typeof json !== 'object' || json === null) return undefined;
  const db = json as Partial<FixtureDatabase>;
  if (db.format !== FIXTURE_DB_FORMAT || typeof db.source !== 'object' || db.source === null) return undefined;
  const { manufacturers, fixtures } = db;
  if (!Array.isArray(manufacturers) || !manufacturers.every((m) => Array.isArray(m) && m.length === 2 && m.every(isString))) return undefined;
  if (!Array.isArray(fixtures)) return undefined;
  for (const f of fixtures) {
    if (!Array.isArray(f) || f.length !== 4 || !isIndex(f[0], manufacturers.length) || !isString(f[1]) || !isString(f[2])) return undefined;
    if (!Array.isArray(f[3]) || f[3].length === 0) return undefined;
    if (new Set(f[3].map((m: unknown) => (Array.isArray(m) ? m[0] : undefined))).size !== f[3].length) return undefined; // mode names unique
    for (const m of f[3]) {
      if (!Array.isArray(m) || m.length !== 2 || !isString(m[0]) || !Array.isArray(m[1]) || m[1].length === 0) return undefined;
      if (!m[1].every(isString)) return undefined;
    }
  }
  return db as FixtureDatabase;
}

/** Expands one database entry. */
export function fixtureAt(db: FixtureDatabase, index: number): Fixture | undefined {
  const f = db.fixtures[index];
  if (!f) return undefined;
  const [mi, key, name, modes] = f;
  const [mKey, manufacturer] = db.manufacturers[mi]!;
  return {
    id: `${mKey}/${key}`,
    manufacturer,
    name,
    modes: modes.map(([modeName, channels]) => ({ name: modeName, channels })),
  };
}

/** Lower case, without diacritics ("Carré" → "carre"), punctuation as spaces. */
export function normalizeSearch(s: string): string {
  return s
    .normalize('NFD')
    .replace(/\p{M}/gu, '')
    .toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .trim();
}

export interface SearchEntry {
  /** normalized "manufacturer name", padded with spaces for word matching */
  readonly text: string;
  /** without spaces, so "mhx25" finds "MH-X25" */
  readonly compact: string;
}

/** Precomputed search text per fixture. */
export function searchIndex(db: FixtureDatabase): SearchEntry[] {
  return db.fixtures.map(([m, , name]) => searchEntry(`${db.manufacturers[m]![1]} ${name}`));
}

export function searchEntry(label: string): SearchEntry {
  const n = normalizeSearch(label);
  return { text: ` ${n} `, compact: n.replace(/ /g, '') };
}

/**
 * Indices of fixtures that contain every word of the query (in manufacturer or name), best first:
 * words at the start of a word rank before matches inside a word, then matches ignoring spaces
 * ("mhx25" → "MH-X25"); ties keep database order
 * (manufacturer, then name).
 */
export function searchFixtures(index: readonly SearchEntry[], query: string, limit = 50): number[] {
  const words = normalizeSearch(query).split(' ').filter(Boolean);
  if (words.length === 0) return [];
  const hits: { i: number; score: number }[] = [];
  index.forEach(({ text, compact }, i) => {
    let score = 0;
    for (const w of words) {
      if (text.includes(` ${w} `)) score += 0;
      else if (text.includes(` ${w}`)) score += 1;
      else if (text.includes(w)) score += 3;
      else if (compact.includes(w)) score += 4;
      else return;
    }
    hits.push({ i, score });
  });
  hits.sort((a, b) => a.score - b.score || a.i - b.i);
  return hits.slice(0, limit).map((h) => h.i);
}
